test("HR-03: six transcripts and six paired feedback files on two candidates and one requisition", () => {
  const transcripts = transcriptNames();
  const feedback = feedbackNames();
  assert.equal(transcripts.length, 6, `HR-03 ships ${transcripts.length} transcripts, expected 6`);
  assert.equal(feedback.length, 6, `HR-03 ships ${feedback.length} feedback files, expected 6`);
  assert.deepEqual(
    feedback.map(pairedTranscript), transcripts,
    "a feedback file has no transcript of the same name, so the pairing is not resolvable from the file names"
  );

  const spec = specs.byId.get("HR-03");
  const candidates = new Set();
  const requisitions = new Set();
  for (const name of transcripts) {
    const meta = metadata(readSource("HR-03", name));
    candidates.add(meta.get("Candidate ID"));
    requisitions.add(meta.get("Requisition ID"));
    const date = meta.get("Date");
    assert.ok(
      date >= spec.period.start && date <= spec.period.end,
      `${name} is dated ${date}, outside the interview window`
    );
    assert.match(name, new RegExp(`^interview-transcript-${meta.get("Candidate ID")}-`), `${name}: the file name and the candidate id disagree`);
  }
  assert.deepEqual([...candidates].sort(), ["ca-001", "ca-002"], "the corpus does not carry exactly ca-001 and ca-002");
  assert.equal(requisitions.size, 1, "the corpus spans more than one requisition");

  // The requisition interviewed is an open one, and it carries no HR-01 plant.
  const reg = register();
  const interviewed = reg.requisitions.find((r) => r.requisition_id === [...requisitions][0]);
  assert.ok(interviewed, "the interviewed requisition does not resolve in the HR-01 register");
  assert.equal(interviewed.status, "open", "the interviewed requisition is not open");
  const rows = byId();
  const list = exclusionPhrases();
  const map = briefs();
  const text = map.get(interviewed.requisition_id).sections.get("Requirements").toLowerCase();
  assert.equal(list.filter((e) => text.includes(e.phrase.toLowerCase())).length, 0, "the interviewed requisition also carries the phrase selection");
  assert.equal(rows.get(interviewed.owner_employee_id).employment_status, "active", "the interviewed requisition also carries the owner selection");
  assert.notEqual(interviewed.target_start_date, "", "the interviewed requisition also carries the absent-field selection");

  // Three conversations per candidate, one per panel role, the same roles both times.
  const perCandidate = {};
  for (const name of transcripts) {
    const m = name.match(/^interview-transcript-(ca-\d{3})-(.+)\.md$/);
    assert.ok(m, `${name}: the file name does not follow the candidate and panel-role convention`);
    (perCandidate[m[1]] ??= []).push(m[2]);
  }
  for (const [candidate, panels] of Object.entries(perCandidate)) {
    assert.equal(panels.length, 3, `${candidate} has ${panels.length} panel conversations, expected 3`);
    assert.equal(new Set(panels).size, 3, `${candidate} carries the same panel role twice`);
  }
});

test("HR-03: every cue parses, timestamps never run backwards, and the bands hold", () => {
  const spec = specs.byId.get("HR-03");
  const active = activeRows();
  const candidateNames = new Set();
  let recruiterSeen = false;

  for (const name of transcriptNames()) {
    const text = readSource("HR-03", name);
    const meta = metadata(text);
    const parsed = cues(text, name);
    assert.ok(parsed.length >= 35 && parsed.length <= 55, `${name} carries ${parsed.length} cues, outside the 35 to 55 band`);
    const count = words(text);
    assert.ok(count >= 900 && count <= 1400, `${name} runs ${count} words, outside the 900 to 1,400 band`);
    for (let i = 1; i < parsed.length; i += 1) {
      assert.ok(
        parsed[i].seconds >= parsed[i - 1].seconds,
        `${name} line ${parsed[i].line}: timestamp ${parsed[i].stamp} runs backwards from ${parsed[i - 1].stamp}`
      );
    }
    const candidateName = meta.get("Candidate name");
    candidateNames.add(candidateName);
    const interviewer = meta.get("Interviewer").match(/^(.+) \(([^()]+)\)$/);
    assert.ok(interviewer, `${name}: the interviewer line is not "Name (Role Title)"`);
    const row = resolveActive(interviewer[1], interviewer[2], `${name} interviewer`, active);
    if (row.department === "People" && row.role_title === "Recruiter") recruiterSeen = true;
    assert.equal(meta.get("Organization"), PROTAGONIST, `${name}: the organization line is not the protagonist`);

    const speakers = new Set(parsed.map((c) => `${c.name} (${c.role})`));
    assert.equal(speakers.size, 2, `${name} carries ${speakers.size} distinct speakers, expected the interviewer and the candidate`);
    for (const cue of parsed) {
      assert.match(cue.name, NAME_SHAPE, `${name} line ${cue.line}: "${cue.name}" is not a First Last name`);
      if (cue.name === candidateName) {
        assert.equal(cue.role, "Candidate", `${name} line ${cue.line}: the candidate speaks under another role`);
        continue;
      }
      resolveActive(cue.name, cue.role, `${name} line ${cue.line}`, active);
    }

    // The competencies assessed are HR-01's own, printed under the library's names.
    const reg = register();
    const named = new Map(reg.competency_library.map((c) => [c.competency_id, c.name]));
    const assessed = text.split("- Competencies assessed:")[1].split("\n\n")[0]
      .split("\n").map((l) => l.match(/^\s+- (.+) \((CMP-\d{2})\)$/)).filter(Boolean);
    assert.ok(assessed.length >= 2, `${name}: fewer than two competencies assessed`);
    for (const m of assessed) {
      assert.equal(m[1], named.get(m[2]), `${name}: ${m[2]} is printed under a name the library does not carry`);
      assert.ok(
        reg.requisitions.find((r) => r.requisition_id === meta.get("Requisition ID")).competencies.includes(m[2]),
        `${name}: ${m[2]} is not on the requisition being interviewed`
      );
    }
    assert.ok(spec.planted_features.length > 0);
  }

  assert.ok(recruiterSeen, "no interviewer in the corpus is a People-department Recruiter");
  // The candidate names are the only names the pack does not already carry.
  const rosterNames = new Set(roster().map(fullName));
  const canonText = readFileSync(join(REPO_ROOT, "canon", "people.md"), "utf8");
  for (const name of candidateNames) {
    assert.ok(!rosterNames.has(name), `the candidate name "${name}" collides with a roster row`);
    for (const part of name.split(" ")) {
      assert.ok(
        !roster().some((r) => r.first_name === part || r.last_name === part),
        `the candidate name "${name}" reuses the roster name part "${part}"`
      );
      assert.ok(!canonText.includes(part), `the candidate name "${name}" reuses the canon name part "${part}"`);
    }
  }
});

test("HR-03: each feedback file sits in its band and carries four to seven numbered claims", () => {
  for (const name of feedbackNames()) {
    const text = readSource("HR-03", name);
    const count = words(text);
    assert.ok(count >= 250 && count <= 400, `${name} runs ${count} words, outside the 250 to 400 band`);
    assert.deepEqual(
      [...sections(text).keys()], ["Recommendation", "Evidence"],
      `${name}: the section order has drifted`
    );
    const claims = claimSentences(text, name);
    assert.ok(claims.length >= 4 && claims.length <= 7, `${name} carries ${claims.length} claim sentences, outside the 4 to 7 band`);
    assert.deepEqual(
      claims.map((c) => c.index), claims.map((_, i) => i + 1),
      `${name}: the claim sentences are not numbered from 1 in order`
    );
    const meta = metadata(text);
    assert.deepEqual([...meta.keys()], FEEDBACK_METADATA_KEYS, `${name}: the metadata key set has drifted from the uniform order`);
    assert.equal(meta.get("Source transcript"), pairedTranscript(name), `${name}: the source transcript line does not name its own pair`);
    const transcriptMeta = metadata(readSource("HR-03", pairedTranscript(name)));
    for (const key of ["Candidate ID", "Candidate name", "Requisition ID", "Date", "Interviewer"]) {
      assert.equal(meta.get(key), transcriptMeta.get(key), `${name}: the ${key} line disagrees with its own transcript`);
    }
    // Every experience claim in the file is a numbered claim sentence, so the
    // population below cannot be understated by a claim hidden in the prose.
    const outside = text.split("## Evidence")[0];
    assert.equal((outside.match(/\byears?\b/gi) ?? []).length, 0, `${name}: an experience claim sits outside the evidence section`);
  }
});

test("HR-C1-T8: exactly one quantified experience claim is unanchored, against the stated population", () => {
  const vocabulary = technologyVocabulary();
  let population = 0;
  let unanchored = 0;
  for (const name of feedbackNames()) {
    const text = readSource("HR-03", name);
    const body = cues(readSource("HR-03", pairedTranscript(name)), pairedTranscript(name))
      .map((c) => c.utterance).join("\n");
    for (const claim of claimSentences(text, name)) {
      for (const pair of quantifiedClaims(claim.sentence, vocabulary)) {
        population += 1;
        if (!claimIsAnchored(pair, body)) unanchored += 1;
      }
    }
  }
  assert.equal(population, 7, `the corpus carries ${population} quantified experience claims, expected the stated population of 7`);
  assert.equal(unanchored, 1, `${unanchored} quantified experience claims are unanchored, expected exactly 1`);
});

