test("HR-09: the pair is a member of the qualifying set, and the log sits in its bands", () => {
  const spec = specs.byId.get("HR-09");
  const rows = roster();
  const active = rows.filter((r) => r.employment_status === "active");
  const log = logFile();
  const review = reviewFile();

  for (const [label, text] of [["log", log], ["review draft", review]]) {
    const meta = metadata(text);
    assert.equal(meta.get("Period"), `${spec.period.start} to ${spec.period.end}`, `the ${label} states another period`);
    const manager = meta.get("Manager").match(/^(.+) \(([^()]+)\)$/);
    const report = meta.get("Report").match(/^(.+) \(([^()]+)\)$/);
    assert.ok(manager && report, `the ${label} metadata is not "Name (Role Title)"`);
    const managerRow = resolveActive(manager[1], manager[2], `the ${label} manager`, active);
    const reportRow = resolveActive(report[1], report[2], `the ${label} report`, active);

    // Membership of the qualifying set, re-derived. The identity inside the set
    // is the drafter's, and this screen never asks which member it is.
    assert.equal(managerRow.department, "People", `the ${label} manager is not a People-department row`);
    assert.equal(managerRow.role_title, "People Manager", `the ${label} manager does not hold People Manager`);
    assert.equal(reportRow.department, "People", `the ${label} report is not a People-department row`);
    assert.equal(reportRow.manager_employee_id, managerRow.employee_id, `the ${label} report does not report to the named manager`);
    assert.ok(reportRow.start_date <= spec.period.start, `the ${label} report started after the review period opened`);
    for (const row of [managerRow, reportRow]) {
      assert.ok(!["EMP-0001", "EMP-0002"].includes(row.employee_id), `the ${label} pair reaches the top of the org tree`);
    }
    const qualifying = active.filter((r) => (
      r.department === "People"
      && r.manager_employee_id === managerRow.employee_id
      && r.start_date <= spec.period.start
      && !["EMP-0001", "EMP-0002"].includes(r.employee_id)
    ));
    assert.ok(qualifying.length > 0, "the qualifying set of reports is empty, so the rule selects nothing");
    assert.ok(
      qualifying.some((r) => r.employee_id === reportRow.employee_id),
      `the ${label} report is not a member of the set the rule selects`
    );
  }

  const entries = logEntries(log);
  assert.equal(entries.length, 12, `the log carries ${entries.length} entries, expected 12`);
  entries.forEach((e, i) => {
    assert.match(e.date, ISO_DATE, `log entry ${i + 1} is not headed by an ISO date`);
    assert.ok(e.date >= spec.period.start && e.date <= spec.period.end, `log entry ${i + 1} is dated outside the period`);
    if (i > 0) assert.ok(e.date > entries[i - 1].date, `log entry ${i + 1} is dated before the entry above it`);
    const count = words(e.body);
    assert.ok(count >= 80 && count <= 150, `log entry ${i + 1} runs ${count} words, outside the 80 to 150 band`);
  });

  const sentences = reviewSentences(review);
  assert.ok(sentences.length >= 14 && sentences.length <= 18, `the review draft carries ${sentences.length} sentences, outside the 14 to 18 band`);
  assert.deepEqual(
    [...sections(review).keys()],
    ["Summary", "What went well", "Where to improve", "Goals for the next period"],
    "the review draft's section order has drifted"
  );

  // Every deliverable the spec publishes is a deliverable the log actually names.
  const { logDeliverables } = hr09Lists();
  const lower = log.toLowerCase();
  for (const name of logDeliverables) {
    assert.ok(lower.includes(name), `the log never names the published deliverable "${name}"`);
  }
});

test("HR-C1-T9: the two review selections each resolve to 1, on two different sentences", () => {
  const { frequencyAdverbs, deadlineLexemes, characterPhrases, logDeliverables } = hr09Lists();
  const log = logFile();
  const entries = logEntries(log);

  // The absence half of the frequency selection: no entry anywhere carries a
  // deadline lexeme, which is what leaves the draft sentence unsupported.
  const entriesWithLexeme = entries.filter((e) => tokensIn(e.body, deadlineLexemes).length > 0);
  assert.equal(entriesWithLexeme.length, 0, `${entriesWithLexeme.length} log entries carry a deadline lexeme, expected 0`);

  const sentences = reviewSentences(reviewFile());
  const frequencySelected = [];
  const characterSelected = [];
  const deadlinePopulation = [];
  const characterPopulation = [];
  sentences.forEach((sentence, index) => {
    const adverbs = tokensIn(sentence, frequencyAdverbs);
    const lexemes = tokensIn(sentence, deadlineLexemes);
    const character = tokensIn(sentence, characterPhrases);
    const named = logDeliverables.filter((d) => sentence.toLowerCase().includes(d));
    if (lexemes.length > 0) deadlinePopulation.push(index);
    if (character.length > 0) characterPopulation.push(index);
    if (adverbs.length > 0 && lexemes.length > 0) frequencySelected.push(index);
    if (character.length > 0 && !isDated(sentence) && named.length === 0) characterSelected.push(index);
  });

  assert.equal(
    frequencySelected.length, 1,
    `${frequencySelected.length} draft sentences pair a frequency adverb with a deadline lexeme, expected 1`
  );
  assert.equal(deadlinePopulation.length, 3, `${deadlinePopulation.length} draft sentences carry a deadline lexeme at all, expected the stated population of 3`);
  assert.equal(
    characterSelected.length, 1,
    `${characterSelected.length} draft sentences carry an unsupported character phrase, expected 1`
  );
  assert.equal(characterPopulation.length, 2, `${characterPopulation.length} draft sentences carry a character phrase at all, expected the stated population of 2`);
  assert.notEqual(
    frequencySelected[0], characterSelected[0],
    "the two selections land on the same sentence, so one revision would close both"
  );

  // The rest of the deadline population is supported: each names a deliverable
  // and a date that resolve to a log entry, and carries no frequency adverb.
  const headings = new Set(entries.map((e) => e.date));
  const MONTH_INDEX = new Map(MONTHS.map((m, i) => [m, String(i + 1).padStart(2, "0")]));
  for (const index of deadlinePopulation) {
    if (index === frequencySelected[0]) continue;
    const sentence = sentences[index];
    assert.equal(tokensIn(sentence, frequencyAdverbs).length, 0, "a supported deadline sentence also carries a frequency adverb");
    const named = logDeliverables.filter((d) => sentence.toLowerCase().includes(d));
    assert.ok(named.length > 0, "a supported deadline sentence names no deliverable the log carries");
    const long = sentence.match(LONG_DATE);
    assert.ok(long, "a supported deadline sentence carries no long-form date");
    const [day, month, year] = long[0].split(" ");
    const iso = `${year}-${MONTH_INDEX.get(month)}-${day.padStart(2, "0")}`;
    assert.ok(headings.has(iso), `a supported deadline sentence cites ${iso}, which heads no log entry`);
    const entry = entries.find((e) => e.date === iso);
    assert.ok(
      named.some((d) => entry.body.toLowerCase().includes(d)),
      "a supported deadline sentence cites a date whose log entry does not discuss the deliverable it names"
    );
  }
});

