test("HR-C1-T10: every printed name and role title lands on an active roster row", () => {
  const active = activeRows();
  const candidateNames = new Set(
    transcriptNames().map((n) => metadata(readSource("HR-03", n)).get("Candidate name"))
  );
  let pairs = 0;
  for (const id of DRAFTED_IDS) {
    for (const { name, text } of allMarkdown(id)) {
      for (const match of text.matchAll(PRINTED_PAIR)) {
        const [, person, role] = match;
        pairs += 1;
        if (candidateNames.has(person)) {
          assert.equal(role, "Candidate", `${id}/${name}: a candidate is printed under the role "${role}"`);
          continue;
        }
        resolveActive(person, role, `${id}/${name}`, active);
      }
    }
  }
  assert.ok(pairs > 0, "no printed name and role pair was found at all, so this screen proves nothing");
});

test("no departed roster employee is named anywhere in the three sets", () => {
  const rows = roster();
  const live = new Set(rows.filter((r) => r.employment_status === "active").map(fullName));
  const departed = [...new Set(rows.filter((r) => r.employment_status !== "active").map(fullName))]
    .filter((name) => !live.has(name));
  assert.ok(departed.length > 0, "the roster carries no departed employees, so this screen proves nothing");
  for (const id of DRAFTED_IDS) {
    for (const { name, text } of allMarkdown(id)) {
      for (const person of departed) {
        assert.ok(!text.includes(person), `${id}/${name} names ${person}, who has left the company`);
      }
    }
  }
});

